-- Module: booking
-- A short, human-readable code for an order (shown to customers, quoted to support).
-- The API still identifies an order by public_id; order_code is for people.
-- The column is added nullable first so existing orders can be backfilled, then locked down.
ALTER TABLE orders
    ADD COLUMN order_code VARCHAR(20);

-- Backfill: same shape as codes generated by the app ("ORDER_" + 13 digits = 19 chars). Padding the
-- internal id keeps the values unique, and the leading zeros keep them apart from new codes, which
-- are built from the current time in milliseconds and therefore never start with zeros.
UPDATE orders
SET order_code = 'ORDER_' || lpad(id::text, 13, '0');

ALTER TABLE orders
    ALTER COLUMN order_code SET NOT NULL;

ALTER TABLE orders
    ADD CONSTRAINT uq_orders_order_code UNIQUE (order_code);
